"""A battle menu that stayed put with no attack command is closed with B.

Owner 2026-11-16: A on the dead きりふだ row does nothing; B closes the modal
menu and the melee resumes (the screen_stalled came from holding/A).
"""
from docich.hanjuku_speedrun.hanjuku.flows.battle_menus import battle_menu_step
from docich.hanjuku_speedrun.hanjuku_font import TextLine
from docich.hanjuku_speedrun.hanjuku_screen import Screen


def menu(rows=('きりふだ', 'たいきゃく')):
    lines = [TextLine(176 + 16 * i, tuple((176 + 8 * j, ch) for j, ch in enumerate(word)))
             for i, word in enumerate(rows)]
    return Screen(lines, None, ''.join(rows), kind='battle_menu')


def test_a_persistent_commandless_menu_is_closed_with_b():
    cur = {'side': 'attack', 'ally': 'ブレッツェル', 'enemy': 'オレガノ'}
    mem = {'chapter': 9, 'battle': cur, '_records': []}
    screen = menu()
    actions = []
    for i in range(14):
        screen.frame_sha256 = 'A' if i % 2 == 0 else 'B'
        actions = battle_menu_step(screen, mem)
        if actions:
            break
    assert actions == [{'type': 'pad', 'buttons': ['b'], 'hold_ms': 100}]


def test_a_menu_with_an_attack_command_is_not_closed():
    cur = {'side': 'attack', 'ally': 'ブレッツェル', 'enemy': 'オレガノ'}
    mem = {'chapter': 9, 'battle': cur, '_records': []}
    screen = menu(('こうげき', 'たいきゃく'))
    for i in range(14):
        screen.frame_sha256 = 'A' if i % 2 == 0 else 'B'
        battle_menu_step(screen, mem)
    assert cur.get('menu_same', 0) >= 10
    assert not any(r.get('decision') == 'battle_menu_close' for r in mem['_records'])
